(()=>{'use strict';
const $=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];
function updateBoard(){const q=($('#work-search')?.value||'').trim().toLocaleLowerCase('es');all('[data-task]').forEach(t=>t.hidden=!t.dataset.task.includes(q));all('[data-stage]').forEach(col=>col.querySelector('[data-stage-count]').textContent=col.querySelectorAll('[data-task]:not([hidden])').length);const done=$('[data-completed]');if(done)done.textContent=String(all('[data-stage]').at(-1).querySelectorAll('[data-task]').length).padStart(2,'0');if($('#work-empty'))$('#work-empty').hidden=all('[data-task]:not([hidden])').length>0;}
all('[data-stage-select]').forEach(select=>select.addEventListener('change',()=>{const target=document.querySelector(`[data-stage="${select.value}"] .work-tasks`);if(target)target.append(select.closest('[data-task]'));updateBoard();}));$('#work-search')?.addEventListener('input',updateBoard);
all('[data-reply]').forEach(b=>b.addEventListener('click',()=>{$('#reply-text').value=b.dataset.reply;$('#reply-text').focus();}));
$('#reply-form')?.addEventListener('submit',e=>{e.preventDefault();const text=$('#reply-text').value.trim();if(!text)return;const message=document.createElement('div');message.className='message-out';message.textContent=text;$('#message-thread').append(message);$('#reply-text').value='';$('#message-thread').scrollTop=$('#message-thread').scrollHeight;});
const money=n=>new Intl.NumberFormat('es-CL',{style:'currency',currency:'CLP',maximumFractionDigits:0}).format(n);
function quote(){const rows=all('[data-quote-row]').map(row=>{const qty=Number(row.querySelector('[data-qty]').value),raw=row.querySelector('[data-price]').value,price=raw===''?null:Number(raw);const valid=Number.isInteger(qty)&&qty>=1&&qty<=10000&&price!==null&&Number.isInteger(price)&&price>=0&&price<=1000000000;return {name:row.querySelector('[data-line-name]').textContent,quantity:qty,unit_price:valid?price:null,total:valid?qty*price:null};});return {demo:true,currency:'CLP',taxes_calculated:false,client:$('#quote-client')?.value||'',conditions:$('#quote-terms')?.value||'',lines:rows,total:rows.some(r=>r.total!==null)?rows.reduce((t,r)=>t+(r.total||0),0):null};}
function updateQuote(){const q=quote();q.lines.forEach((line,i)=>all('[data-line-total]')[i].textContent=line.total===null?'Por definir':money(line.total));$('[data-quote-total]').textContent=q.total===null?'Por definir':money(q.total);const pending=q.lines.filter(r=>r.total===null).length;$('[data-quote-note]').textContent=pending?`${pending} concepto(s) pendiente(s) de un precio o cantidad válidos.`:'Todos los conceptos tienen un importe. Revisa los datos antes de usar el borrador.';}
all('[data-qty],[data-price]').forEach(input=>input.addEventListener('input',updateQuote));
$('[data-quote-download]')?.addEventListener('click',()=>{const blob=new Blob([JSON.stringify(quote(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='cotizacion-borrador.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
$('[data-print]')?.addEventListener('click',()=>window.print());
})();
